#!/usr/bin/env swift
// Generates ios/App/Design/Tokens.generated.swift from shared/design/tokens.json.
//
//   swift ios/scripts/gen-tokens.swift            (from the repository root)
//   swift ios/scripts/gen-tokens.swift --check    (exit 1 if the generated file is stale)
//
// The output is committed; TokensTests also fails if it drifts from tokens.json.

import Foundation

let scriptURL = URL(fileURLWithPath: CommandLine.arguments[0]).standardizedFileURL
let root = scriptURL.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
let input = root.appendingPathComponent("shared/design/tokens.json")
let output = root.appendingPathComponent("ios/App/Design/Tokens.generated.swift")
let check = CommandLine.arguments.contains("--check")

func fail(_ message: String) -> Never {
    FileHandle.standardError.write(Data("gen-tokens: \(message)\n".utf8))
    exit(1)
}

guard let data = try? Data(contentsOf: input),
      let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { fail("cannot read \(input.path)") }

func object(_ key: String) -> [String: Any] {
    guard let o = json[key] as? [String: Any] else { fail("missing object \(key)") }
    return o
}

func hex(_ value: Any, _ name: String) -> String {
    guard let s = value as? String, s.hasPrefix("#"), s.count == 7, UInt32(s.dropFirst(), radix: 16) != nil else { fail("bad colour \(name)") }
    return "0x" + s.dropFirst().uppercased()
}

func number(_ value: Any, _ name: String) -> String {
    guard let n = value as? NSNumber else { fail("bad number \(name)") }
    let d = n.doubleValue
    return d == d.rounded() ? String(format: "%.1f", d) : String(d)
}

var out = """
// Generated by ios/scripts/gen-tokens.swift from shared/design/tokens.json. Do not edit by hand.
// swiftlint:disable all

import CoreGraphics

enum Tokens {

"""

// Palette
let palette = object("palette")
out += "    enum Palette {\n"
for key in palette.keys.sorted() { out += "        static let \(key): UInt32 = \(hex(palette[key]!, key))\n" }
out += "    }\n\n"

// Schemes: dark is complete; light = explicit + Material defaults Theme.kt leaves unset.
let dark = object("dark")
var light = object("lightMaterialDefaults")
for (k, v) in object("light") { light[k] = v }
let roles = dark.keys.sorted()
guard Set(roles) == Set(light.keys) else {
    fail("light and dark schemes define different roles: \(Set(roles).symmetricDifference(light.keys).sorted())")
}
out += "    struct Scheme: Sendable {\n"
for role in roles { out += "        let \(role): UInt32\n" }
out += "    }\n\n"
for (name, scheme) in [("dark", dark), ("light", light)] {
    out += "    static let \(name) = Scheme(\n"
    out += roles.map { "        \($0): \(hex(scheme[$0]!, "\(name).\($0)"))" }.joined(separator: ",\n")
    out += "\n    )\n\n"
}
let amoled = object("amoled")
out += "    /// Dark-scheme overrides for pure-black OLED panels.\n    enum Amoled {\n"
for key in amoled.keys.sorted() {
    guard dark[key] != nil else { fail("amoled overrides unknown role \(key)") }
    out += "        static let \(key): UInt32 = \(hex(amoled[key]!, key))\n"
}
out += "    }\n\n"

// Accent inks: the palette accents as text and glyphs, per ground (dark = ink, light = paper).
let inks = object("inks")
guard let darkInks = inks["dark"] as? [String: Any], let lightInks = inks["light"] as? [String: Any],
      Set(darkInks.keys) == Set(lightInks.keys) else { fail("inks needs dark and light with the same keys") }
let inkKeys = darkInks.keys.sorted()
out += "    /// Accent colours as text and glyphs on each ground (the palette accents are for fills).\n"
out += "    struct Inks: Sendable {\n"
for key in inkKeys { out += "        let \(key): UInt32\n" }
out += "    }\n\n"
for (name, set) in [("darkInks", darkInks), ("lightInks", lightInks)] {
    out += "    static let \(name) = Inks(\n"
    out += inkKeys.map { "        \($0): \(hex(set[$0]!, "inks.\(name).\($0)"))" }.joined(separator: ",\n")
    out += "\n    )\n\n"
}

// Type scale
let type = object("type")
out += """
    enum FontRole: Sendable { case display, mono, sans }

    struct TypeStyle: Sendable {
        let font: FontRole
        let size: CGFloat
        let lineHeight: CGFloat
        let weight: CGFloat
        let letterSpacing: CGFloat
        /// Compose `LineHeightStyle.Trim.Both`: no extra leading above the first / below the last line.
        let trim: Bool
        let tabular: Bool
    }

    enum Typography {

"""
for key in type.keys.sorted() {
    guard let s = type[key] as? [String: Any], let font = s["font"] as? String else { fail("bad type style \(key)") }
    let trim = (s["trim"] as? Bool) ?? false
    let tabular = (s["tabular"] as? Bool) ?? false
    out += "        static let \(key) = TypeStyle(font: .\(font), size: \(number(s["size"]!, key)), lineHeight: \(number(s["lineHeight"]!, key)), "
    out += "weight: \(number(s["weight"]!, key)), letterSpacing: \(number(s["letterSpacing"]!, key)), trim: \(trim), tabular: \(tabular))\n"
}
out += "    }\n\n"

// Plain number groups
for (group, typeName) in [("radius", "Radius"), ("stroke", "Stroke"), ("spacing", "Spacing"), ("halftone", "Halftone"), ("motion", "Motion")] {
    let o = object(group)
    out += "    enum \(typeName) {\n"
    for key in o.keys.sorted() { out += "        static let \(key): CGFloat = \(number(o[key]!, "\(group).\(key)"))\n" }
    out += "    }\n\n"
}
out.removeLast()
out += "}\n"

if check {
    let current = (try? String(contentsOf: output, encoding: .utf8)) ?? ""
    if current != out { fail("\(output.path) is stale; run swift ios/scripts/gen-tokens.swift") }
    print("gen-tokens: up to date")
} else {
    try? FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
    do { try out.write(to: output, atomically: true, encoding: .utf8) } catch { fail("cannot write \(output.path): \(error)") }
    print("gen-tokens: wrote \(output.path)")
}
